import { test, expect } from '@playwright/test';

test.describe('File Upload Progress Bar', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/upload'); // Replace with the actual URL
  });

  test('should display progress bar when a file is uploaded', async ({ page }) => {
    const filePath = 'path/to/your/file.txt'; // Replace with the actual file path
    await page.getByLabel('Upload File').setInputFiles(filePath);

    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();
    await expect(progressBar).toHaveAttribute('aria-valuenow', '0'); // Assuming it starts at 0

    // Wait for the progress bar to update
    await page.waitForTimeout(2000); // Adjust timeout as necessary
    await expect(progressBar).toHaveAttribute('aria-valuenow', '100'); // Assuming it ends at 100
  });

  test('should not display progress bar if no file is uploaded', async ({ page }) => {
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).not.toBeVisible();
  });
});
